  @protected
  void sse_encode_session_event(SessionEvent self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case SessionEvent_Opened(sessionId: final sessionId):
        sse_encode_i_32(0, serializer);
        sse_encode_u_32(sessionId, serializer);
      case SessionEvent_Connected(description: final description):
        sse_encode_i_32(1, serializer);
        sse_encode_String(description, serializer);
      case SessionEvent_Output(data: final data):
        sse_encode_i_32(2, serializer);
        sse_encode_list_prim_u_8_strict(data, serializer);
      case SessionEvent_HostKey(
        requestId: final requestId,
        host: final host,
        port: final port,
        algorithm: final algorithm,
        fingerprint: final fingerprint,
        knownFingerprints: final knownFingerprints,
      ):
        sse_encode_i_32(3, serializer);
        sse_encode_u_32(requestId, serializer);
        sse_encode_String(host, serializer);
        sse_encode_u_16(port, serializer);
        sse_encode_String(algorithm, serializer);
        sse_encode_String(fingerprint, serializer);
        sse_encode_list_String(knownFingerprints, serializer);
      case SessionEvent_Password(
        requestId: final requestId,
        prompt: final prompt,
      ):
        sse_encode_i_32(4, serializer);
        sse_encode_u_32(requestId, serializer);
        sse_encode_String(prompt, serializer);
      case SessionEvent_ServerPrompts(
        requestId: final requestId,
        name: final name,
        instructions: final instructions,
        prompts: final prompts,
      ):
        sse_encode_i_32(5, serializer);
        sse_encode_u_32(requestId, serializer);
        sse_encode_String(name, serializer);
        sse_encode_String(instructions, serializer);
        sse_encode_list_prompt_view(prompts, serializer);
      case SessionEvent_Exit(code: final code):
        sse_encode_i_32(6, serializer);
        sse_encode_opt_box_autoadd_u_32(code, serializer);
      case SessionEvent_Failed(message: final message):
        sse_encode_i_32(7, serializer);
        sse_encode_String(message, serializer);
      case SessionEvent_Closed():
        sse_encode_i_32(8, serializer);
    }
  }

